{
  "thought": "I will implement `apply_discounts` in `src/ledgerlib/apply_discounts.py`. I'll use `parse_amount` to parse the discount values and `round_div` to handle the percentage calculation. I'll ensure percentages are applied first, then fixed amounts, and the final amount is not less than 0.",
  "action": {
    "tool": "write_file",
    "args": {
      "path": "src/ledgerlib/apply_discounts.py",
      "content": "from __future__ import annotations

from typing import Sequence

from ledgerlib.parse_amount import parse_amount
from ledgerlib.round_div import round_div


def apply_discounts(amount_cents: int, discounts: Sequence[str]) -> int:
    """
    Apply a list of promotional discounts to an amount and return the discounted
    amount in cents.

    Each discount is a string, either
      * a percentage such as "10%" or "12.5%": the number before '%' is parsed with
        parse_amount, which yields hundredths of a percent (basis points); the discount is
        that share of the current amount, rounded half up to cents with round_div, or
      * a fixed amount such as "5.00" or "$5" (parsed with parse_amount), which is
        subtracted.

    The result is never below 0. Raises ValueError for a discount that cannot be parsed, a
    negative discount, or a percentage above 100%.

    Examples:
        apply_discounts(10000, ["10%"]) == 9000
        apply_discounts(10000, ["$5"]) == 9500
    """
    current_amount = amount_cents
    percentage_discounts: list[int] = []
    fixed_discounts: list[int] = []

    for d in discounts:
        if d.endswith("%"):
            try:
                # parse_amount returns cents, e.g., "10.5" -> 1050
                # The docstring says this represents basis points.
                basis_points = parse_amount(d[:-1])
            except ValueError as e:
                raise ValueError(f"Invalid percentage discount: {d}") from e

            if basis_points < 0:
                raise ValueError(f"Negative percentage discount: {d}")
            if basis_points > 10000:
                raise ValueError(f"Percentage discount above 100%: {d}")
            percentage_discounts.append(basis_points)
        else:
            try:
                fixed_amount = parse_amount(d)
            except ValueError as e:
                raise ValueError(f"Invalid fixed discount: {d}") from e

            if fixed_amount < 0:
                raise ValueError(f"Negative fixed discount: {d}")
            fixed_discounts.append(fixed_amount)

    # Apply percentages first
    for bp in percentage_discounts:
        discount_amount = round_div(current_amount * bp, 10000)
        current_amount -= discount_amount

    # Apply fixed amounts second
    for fixed in fixed_discounts:
        current_amount -= fixed

    return max(0, current_amount)
"
